/* @lc app=leetcode id=3694 lang=kotlin */ class Solution { fun distinctPoints(s: String, k: Int): Int = s.runningFold(0 to 0) { (x, y), c -> if (c == 'U') x to y + 1 else if (c == 'D') x to y - 1 else if (c == 'L') x - 1 to y else x + 1 to y }.let { pre -> (0..s.length - k).map { i -> (pre[i].first + pre.last().first - pre[i + k].first) to (pre[i].second + pre.last().second - pre[i + k].second) }.toSet().size } }